#include <vector>
#include <algorithm>

class Solution {
public:
    long long minPartitionScore(std::vector<int>& nums, int k) {
        int n = nums.size();
        std::vector<long long> pref(n + 1, 0);
        for (int i = 0; i < n; ++i) pref[i + 1] = pref[i] + nums[i];

        auto cost = [&](int i, int j) -> long long {
            long long s = pref[j] - pref[i];
            return s * (s + 1) / 2;
        };

        std::vector<long long> dp(n + 1, 1e18);
        dp[0] = 0;
        for (int p = 1; p <= k; ++p) {
            std::vector<long long> nextDp(n + 1, 1e18);
            for (int i = p; i <= n; ++i) {
                for (int m = p - 1; m < i; ++m) {
                    nextDp[i] = std::min(nextDp[i], dp[m] + cost(m, i));
                }
            }
            dp = std::move(nextDp);
        }
        return dp[n];
    }
};

import java.util.*;

class Solution {
    public long minPartitionScore(int[] nums, int k) {
        int n = nums.length;
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) pref[i + 1] = pref[i] + nums[i];

        long[] dp = new long[n + 1];
        Arrays.fill(dp, Long.MAX_VALUE / 2);
        dp[0] = 0;
        for (int p = 1; p <= k; p++) {
            long[] nextDp = new long[n + 1];
            Arrays.fill(nextDp, Long.MAX_VALUE / 2);
            for (int i = p; i <= n; i++) {
                for (int m = p - 1; m < i; m++) {
                    long s = pref[i] - pref[m];
                    long cost = s * (s + 1) / 2;
                    nextDp[i] = Math.min(nextDp[i], dp[m] + cost);
                }
            }
            dp = nextDp;
        }
        return dp[n];
    }
}

